CREATE TABLE organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL);
CREATE TABLE stores (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, name text NOT NULL, currency text NOT NULL, timezone text NOT NULL);
CREATE TABLE roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_id uuid NOT NULL REFERENCES stores, name text NOT NULL, permissions jsonb NOT NULL, UNIQUE(id,store_id));
CREATE TABLE employees (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_id uuid NOT NULL REFERENCES stores, role_id uuid NOT NULL REFERENCES roles, name text NOT NULL, email text NOT NULL UNIQUE, password_hash text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,store_id), FOREIGN KEY(role_id,store_id) REFERENCES roles(id,store_id));
CREATE TABLE devices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_id uuid NOT NULL REFERENCES stores, name text NOT NULL, type text NOT NULL DEFAULT 'management', token_hash text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,store_id));
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), token_hash text NOT NULL UNIQUE, employee_id uuid NOT NULL REFERENCES employees, device_id uuid NOT NULL REFERENCES devices, expires_at timestamptz NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_id uuid NOT NULL REFERENCES stores, name text NOT NULL, sku text NOT NULL, category text NOT NULL, unit text NOT NULL CHECK(unit IN ('piece','kilogram','gram','liter','milliliter','pack','box','other')), price numeric(14,2) NOT NULL CHECK(price>=0), cost numeric(14,2) NOT NULL CHECK(cost>=0), min_stock numeric(15,3) NOT NULL CHECK(min_stock>=0), stock numeric(15,3) NOT NULL DEFAULT 0 CHECK(stock>=0), plu text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(store_id,sku), UNIQUE(store_id,plu), UNIQUE(id,store_id));
CREATE TABLE barcodes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_id uuid NOT NULL REFERENCES stores, product_id uuid NOT NULL REFERENCES products, value text NOT NULL, UNIQUE(store_id,value), FOREIGN KEY(product_id,store_id) REFERENCES products(id,store_id));
CREATE TABLE movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_id uuid NOT NULL REFERENCES stores, product_id uuid NOT NULL REFERENCES products, employee_id uuid NOT NULL REFERENCES employees, device_id uuid NOT NULL REFERENCES devices, quantity numeric(15,3) NOT NULL CHECK(quantity<>0), balance numeric(15,3) NOT NULL CHECK(balance>=0), reason text NOT NULL, notes text NOT NULL, request_id uuid NOT NULL, request_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(store_id,request_id), FOREIGN KEY(product_id,store_id) REFERENCES products(id,store_id), FOREIGN KEY(employee_id,store_id) REFERENCES employees(id,store_id), FOREIGN KEY(device_id,store_id) REFERENCES devices(id,store_id));
CREATE INDEX movements_store_date ON movements(store_id,created_at DESC);
CREATE TABLE audits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_id uuid NOT NULL REFERENCES stores, employee_id uuid NOT NULL REFERENCES employees, device_id uuid NOT NULL REFERENCES devices, action text NOT NULL, entity_id uuid NOT NULL, details jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(employee_id,store_id) REFERENCES employees(id,store_id), FOREIGN KEY(device_id,store_id) REFERENCES devices(id,store_id));
CREATE INDEX audits_store_date ON audits(store_id,created_at DESC);
CREATE FUNCTION prevent_history_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'History is append-only; create a compensating record'; END $$;
CREATE TRIGGER immutable_movements BEFORE UPDATE OR DELETE ON movements FOR EACH ROW EXECUTE FUNCTION prevent_history_mutation();
CREATE TRIGGER immutable_audits BEFORE UPDATE OR DELETE ON audits FOR EACH ROW EXECUTE FUNCTION prevent_history_mutation();
